from __future__ import annotations

# Seeded billing rows. Each row records the account id that owns it in ``owner_id``.
_INVOICES = {
    "INV-4185": {
        "id": "INV-4185",
        "owner_id": "u-2075",
        "amount_cents": 128400,
        "currency": "USD",
        "status": "open",
    },
    "INV-4192": {
        "id": "INV-4192",
        "owner_id": "u-3310",
        "amount_cents": 906050,
        "currency": "USD",
        "status": "paid",
    },
}

_PAYMENT_METHODS = {
    "PM-8801": {"id": "PM-8801", "owner_id": "u-2075", "brand": "visa", "last4": "4471"},
    "PM-8802": {"id": "PM-8802", "owner_id": "u-3310", "brand": "amex", "last4": "0092"},
}


def find_invoice(invoice_id: str) -> dict | None:
    """Return the invoice row for ``invoice_id``, or ``None`` if there is none.

    Primary-key lookup only — it does not consider who is asking.
    """
    return _INVOICES.get(invoice_id)


def find_payment_method(payment_method_id: str) -> dict | None:
    """Return the payment-method row for ``payment_method_id``, or ``None``. Key lookup only."""
    return _PAYMENT_METHODS.get(payment_method_id)

"""Local directory-authorized entry point (no network input)."""
from billing import get_invoice
DIRECTORY_USERS = frozenset({'u-2075', 'u-3310', 'demo-reviewer'})
def read_invoice(invoice_id, user):
    if user not in DIRECTORY_USERS: raise PermissionError('directory access required')
    return get_invoice(invoice_id, user)

import unittest

from billing import get_invoice, get_payment_method


class GetInvoiceContractTest(unittest.TestCase):
    def test_returns_owned_invoice_fields(self):
        inv = get_invoice("INV-4185", "u-2075")
        self.assertEqual(inv["id"], "INV-4185")
        self.assertEqual(inv["amount_cents"], 128400)
        self.assertEqual(inv["status"], "open")

    def test_returns_owned_invoice_for_other_account(self):
        inv = get_invoice("INV-4192", "u-3310")
        self.assertEqual(inv["owner_id"], "u-3310")
        self.assertEqual(inv["status"], "paid")


class GetPaymentMethodTest(unittest.TestCase):
    def test_owner_can_read_payment_method(self):
        pm = get_payment_method("PM-8801", "u-2075")
        self.assertEqual(pm["last4"], "4471")


if __name__ == "__main__":
    unittest.main()

